<?php
include 'includes/session.php';include 'includes/functions.php';if(empty($_SESSION['userId'])||!in_array($_SESSION['role']??'', ['Admin','Manager'],true)){http_response_code(403);exit;}$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['from']??'')?$_GET['from']:date('Y-m-01');$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['to']??'')?$_GET['to']:date('Y-m-d');$s=$conn->prepare("SELECT day,reference,description,income,expense,income-expense net FROM (SELECT DATE(p.PaymentDate) day,p.receipt_no reference,CONCAT('Membership payment - ',m.FullName) description,p.amount income,0 expense FROM payments p JOIN members m ON m.id=p.member_id WHERE DATE(p.PaymentDate) BETWEEN ? AND ? UNION ALL SELECT e.expense_date,e.expense_no,CONCAT(c.name,' - ',e.payee),0,e.amount FROM expenses e JOIN expense_categories c ON c.id=e.category_id WHERE e.expense_date BETWEEN ? AND ?)x ORDER BY day,reference");$s->execute([$from,$to,$from,$to]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="gym-financial-report-'.$from.'-'.$to.'.csv"');$o=fopen('php://output','w');fputcsv($o,['Date','Reference','Description','Income','Expense','Net']);foreach($s as $r)fputcsv($o,$r);fclose($o);
